new ResizeObserver(hideSeekPreview).observe(ui.seek);
ui.seek.addEventListener('input',()=>{if(!blocked('playback'))engine.seek(+ui.seek.value)});ui.volume.addEventListener('input',()=>{if(!blocked('playback')){s.settings.volume=+ui.volume.value;engine.applyVolume();ui.volumeLabel.textContent=Math.round(s.settings.volume*100)+'%';changed('checkpoint')}});
