function installFileDrop(target){
 const hasFiles=e=>[...(e.dataTransfer?.types||[])].includes('Files');
 target.addEventListener('dragover',e=>{if(!hasFiles(e))return;e.preventDefault();e.stopPropagation();if(e.dataTransfer)e.dataTransfer.dropEffect=blocked('edits')?'none':'copy';target.classList.toggle('drop-target',!blocked('edits'))});
 target.addEventListener('dragleave',e=>{if(!target.contains(e.relatedTarget))target.classList.remove('drop-target')});
 target.addEventListener('drop',async e=>{if(!hasFiles(e))return;e.preventDefault();e.stopPropagation();target.classList.remove('drop-target');ui.player.classList.remove('drop-target');if(blocked('edits'))return;try{const files=await droppedAudioFiles(e.dataTransfer);if(blocked('edits'))return;if(!files.length){toast('No audio files in this selection');return}await addLocal(files);toast(`Added ${files.length} ${files.length===1?'track':'tracks'} · playback unchanged`)}catch(err){error(err)}});
}

